body.script:
    (function () {
      "use strict";

      const STORAGE_KEY = "tribute_guru_galeri_v1";

      const defaultGallery = [
        {
          src: "foto1.jpg",
          tag: "MOMEN KELAS",
          title: "Diskusi Penuh Semangat",
          desc: "Suasana ruang belajar yang hidup ketika setiap pertanyaan disambut dengan kesabaran dan kejelasan."
        },
        {
          src: "foto2.jpg",
          tag: "KENANGAN BERSAMA",
          title: "Jejak Langkah & Nasihat",
          desc: "Momen kebersamaan di kelas yang menjadi pengingat keteladanan dan bimbingan tulus Bapak/Ibu."
        }
      ];

      const TributeApp = {
        soundEnabled: false,
        audioCtx: null,
        ambientInterval: null,
        quoteIndex: 0,
        activeGalleryIndex: 0,
        uploadedDataUrl: "",
        giftOpened: false,
        particles: [],
        canvas: null,
        ctx: null,
        touchLayer: null,

        quotes: [
          "“Guru menyalakan pelita, bukan sekadar mengisi bejana—agar murid mampu melihat jalan sendiri.”",
          "“Satu kalimat penyemangat dari guru yang tepat bisa mengubah arah hidup seseorang selamanya.”",
          "“Kesabaran seorang pendidik adalah bahasa cinta paling sunyi namun paling kuat.”",
          "“Ilmu yang diajarkan dengan hati akan selalu menemukan jalan untuk pulang menjadi kebaikan.”"
        ],

        galleryItems: [],

        loadGallery() {
          try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (raw) {
              const parsed = JSON.parse(raw);
              if (Array.isArray(parsed) && parsed.length > 0) {
                this.galleryItems = parsed;
                return;
              }
            }
          } catch (err) {}
          this.galleryItems = defaultGallery.map((item) => ({ ...item }));
        },

        saveGallery() {
          try {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(this.galleryItems));
          } catch (err) {}
        },

        init() {
          this.loadGallery();
          this.canvas = document.getElementById("particle-canvas");
          this.ctx = this.canvas ? this.canvas.getContext("2d") : null;
          this.touchLayer = document.getElementById("touch-layer");

          this.setupParticles();
          this.setupSound();
          this.setupTouchEffects();
          this.setupScrollAnimations();
          this.setupQuotes();
          this.setupGalleryAndLightbox();
          this.setupGiftSection();
          this.setupEndingSection();
          this.setupNavigationAndActions();
        },
                setupSound() {
          const btn = document.getElementById("soundToggle");
          const label = document.getElementById("soundLabel");
          if (!btn || !label) return;

          const ensureCtx = () => {
            if (!this.audioCtx) {
              const AudioContext = window.AudioContext || window.webkitAudioContext;
              if (AudioContext) this.audioCtx = new AudioContext();
            }
            if (this.audioCtx && this.audioCtx.state === "suspended") {
              this.audioCtx.resume();
            }
          };

          this.playTone = (freq = 523.25, duration = 0.22, type = "sine", gainVal = 0.06) => {
            if (!this.soundEnabled) return;
            ensureCtx();
            if (!this.audioCtx) return;

            const now = this.audioCtx.currentTime;
            const osc = this.audioCtx.createOscillator();
            const gain = this.audioCtx.createGain();
            osc.type = type;
            osc.frequency.setValueAtTime(freq, now);

            gain.gain.setValueAtTime(0.0001, now);
            gain.gain.exponentialRampToValueAtTime(gainVal, now + 0.02);
            gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

            osc.connect(gain);
            gain.connect(this.audioCtx.destination);
            osc.start(now);
            osc.stop(now + duration + 0.02);
          };

          this.playChimeChord = () => {
            [523.25, 659.25, 783.99, 1046.5].forEach((n, idx) => {
              setTimeout(() => this.playTone(n, 0.55, "triangle", 0.05), idx * 90);
            });
          };

          const startAmbient = () => {
            this.stopAmbient();
            const notes = [261.63, 329.63, 392.0, 493.88, 587.33];
            let step = 0;
            this.ambientInterval = setInterval(() => {
              if (!this.soundEnabled) return;
              this.playTone(notes[step % notes.length], 1.1, "sine", 0.022);
              step++;
            }, 1900);
          };

          this.stopAmbient = () => {
            if (this.ambientInterval) {
              clearInterval(this.ambientInterval);
              this.ambientInterval = null;
            }
          };

          btn.addEventListener("click", (e) => {
            e.stopPropagation();
            this.soundEnabled = !this.soundEnabled;
            ensureCtx();
            btn.classList.toggle("is-playing", this.soundEnabled);
            label.textContent = this.soundEnabled ? "Suara: On" : "Suara: Off";

            if (this.soundEnabled) {
              this.playChimeChord();
              startAmbient();
            } else {
              this.stopAmbient();
            }
          });
        },

        setupTouchEffects() {
          if (!this.touchLayer) return;

          const spawnTouch = (x, y) => {
            const ripple = document.createElement("span");
            ripple.className = "touch-ripple";
            ripple.style.left = `${x}px`;
            ripple.style.top = `${y}px`;
            ripple.style.width = "34px";
            ripple.style.height = "34px";
            this.touchLayer.appendChild(ripple);
            setTimeout(() => ripple.remove(), 700);

            const count = 6;
            for (let i = 0; i < count; i++) {
              const spark = document.createElement("span");
              spark.className = "touch-spark";
              spark.style.left = `${x}px`;
              spark.style.top = `${y}px`;
              this.touchLayer.appendChild(spark);

              const angle = (Math.PI * 2 * i) / count;
              const dist = 26 + Math.random() * 20;
              requestAnimationFrame(() => {
                spark.style.transform = `translate(calc(-50% + ${Math.cos(angle) * dist}px), calc(-50% + ${Math.sin(angle) * dist}px)) scale(0.2)`;
                spark.style.opacity = "0";
              });
              setTimeout(() => spark.remove(), 600);
            }

            if (this.soundEnabled) {
              this.playTone(587.33 + Math.random() * 140, 0.14, "sine", 0.035);
            }
          };

          document.addEventListener("pointerdown", (e) => {
            spawnTouch(e.clientX, e.clientY);
          });
        },

        setupParticles() {
          if (!this.canvas || !this.ctx) return;

          const resize = () => {
            const dpr = Math.min(window.devicePixelRatio || 1, 2);
            this.canvas.width = window.innerWidth * dpr;
            this.canvas.height = window.innerHeight * dpr;
            this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
          };

          resize();
          window.addEventListener("resize", resize);

          const total = window.innerWidth < 480 ? 28 : 44;
          this.particles = Array.from({ length: total }, () => ({
            x: Math.random() * window.innerWidth,
            y: Math.random() * window.innerHeight,
            r: 1 + Math.random() * 2.2,
            vx: (Math.random() - 0.5) * 0.28,
            vy: -0.15 - Math.random() * 0.35,
            alpha: 0.2 + Math.random() * 0.55,
            phase: Math.random() * Math.PI * 2
          }));

          this.burstParticles = (cx, cy, amount = 24) => {
            for (let i = 0; i < amount; i++) {
              const angle = Math.random() * Math.PI * 2;
              const speed = 1.2 + Math.random() * 3.6;
              this.particles.push({
                x: cx,
                y: cy,
                r: 1.8 + Math.random() * 2.4,
                vx: Math.cos(angle) * speed,
                vy: Math.sin(angle) * speed - 0.8,
                alpha: 1,
                phase: Math.random() * Math.PI * 2,
                burst: true
              });
            }
          };

          const render = () => {
            this.ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);

            for (let i = this.particles.length - 1; i >= 0; i--) {
              const p = this.particles[i];
              p.x += p.vx;
              p.y += p.vy;
              p.phase += 0.03;

              if (p.burst) {
                p.vy += 0.04;
                p.alpha -= 0.016;
                if (p.alpha <= 0) {
                  this.particles.splice(i, 1);
                  continue;
                }
              } else {
                if (p.y < -10) p.y = window.innerHeight + 10;
                if (p.x < -10) p.x = window.innerWidth + 10;
                if (p.x > window.innerWidth + 10) p.x = -10;
              }

              const twinkle = p.burst ? p.alpha : p.alpha * (0.65 + 0.35 * Math.sin(p.phase));
              this.ctx.beginPath();
              this.ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
              this.ctx.fillStyle = `rgba(247, 223, 156, ${Math.max(0, twinkle)})`;
              this.ctx.fill();
            }

            requestAnimationFrame(render);
          };

          render();
        },

        setupScrollAnimations() {
          const progressBar = document.getElementById("scrollProgress");
          const reveals = document.querySelectorAll(".reveal");

          const updateProgress = () => {
            const scrollTop = window.scrollY || document.documentElement.scrollTop;
            const docHeight = document.documentElement.scrollHeight - window.innerHeight;
            const pct = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
            if (progressBar) progressBar.style.width = `${Math.min(100, Math.max(0, pct))}%`;
          };

          window.addEventListener("scroll", updateProgress, { passive: true });
          updateProgress();

          if ("IntersectionObserver" in window) {
            const observer = new IntersectionObserver(
              (entries) => {
                entries.forEach((entry) => {
                  if (entry.isIntersecting) {
                    entry.target.classList.add("is-revealed");
                    observer.unobserve(entry.target);
                  }
                });
              },
              { threshold: 0.12, rootMargin: "0px 0px -30px 0px" }
            );
            reveals.forEach((el) => observer.observe(el));
          } else {
            reveals.forEach((el) => el.classList.add("is-revealed"));
          }
        },

        setupQuotes() {
          const display = document.getElementById("quoteDisplay");
          const dotsWrap = document.getElementById("quoteDots");
          const prevBtn = document.getElementById("prevQuoteBtn");
          const nextBtn = document.getElementById("nextQuoteBtn");
          if (!display || !dotsWrap) return;

          const renderDots = () => {
            dotsWrap.innerHTML = "";
            this.quotes.forEach((_, idx) => {
              const dot = document.createElement("button");
              dot.type = "button";
              dot.className = `quote-dot ${idx === this.quoteIndex ? "active" : ""}`;
              dot.setAttribute("aria-label", `Kutipan ${idx + 1}`);
              dot.addEventListener("click", () => goTo(idx));
              dotsWrap.appendChild(dot);
            });
          };

          const goTo = (idx) => {
            this.quoteIndex = (idx + this.quotes.length) % this.quotes.length;
            display.style.opacity = "0";
            display.style.transform = "translateY(8px)";
            setTimeout(() => {
              display.textContent = this.quotes[this.quoteIndex];
              display.style.opacity = "1";
              display.style.transform = "translateY(0)";
              renderDots();
            }, 160);
            if (this.soundEnabled) this.playTone(440 + this.quoteIndex * 55, 0.18, "triangle", 0.04);
          };

          if (prevBtn) prevBtn.addEventListener("click", () => goTo(this.quoteIndex - 1));
          if (nextBtn) nextBtn.addEventListener("click", () => goTo(this.quoteIndex + 1));
          renderDots();
        },

        setupGalleryAndLightbox() {
          const grid = document.getElementById("galleryGrid");
          const form = document.getElementById("addPhotoForm");
          const srcInput = document.getElementById("photoSrcInput");
          const fileInput = document.getElementById("photoFileInput");
          const fileHint = document.getElementById("selectedFileHint");
          const tagInput = document.getElementById("photoTagInput");
          const titleInput = document.getElementById("photoTitleInput");
          const descInput = document.getElementById("photoDescInput");
          const resetBtn = document.getElementById("resetPhotosBtn");

          const lightbox = document.getElementById("lightbox");
          const visual = document.getElementById("lightboxVisual");
          const yearEl = document.getElementById("lightboxYear");
          const titleEl = document.getElementById("lightboxTitle");
          const descEl = document.getElementById("lightboxDesc");
          const closeBtn = document.getElementById("closeLightboxBtn");
          const prevBtn = document.getElementById("prevPhotoBtn");
          const nextBtn = document.getElementById("nextPhotoBtn");
          if (!grid || !lightbox) return;

          const openLightbox = (index) => {
            if (!this.galleryItems.length) return;
            this.activeGalleryIndex = (index + this.galleryItems.length) % this.galleryItems.length;
            const item = this.galleryItems[this.activeGalleryIndex];
            if (visual) {
              visual.innerHTML = ``;
            }
            if (yearEl) yearEl.textContent = item.tag || "MOMEN KELAS";
            if (titleEl) titleEl.textContent = item.title;
            if (descEl) descEl.textContent = item.desc || "Kenangan berharga bersama.";

            lightbox.classList.add("is-visible");
            if (this.soundEnabled) this.playTone(659.25, 0.24, "sine", 0.05);
          };

          const closeLightbox = () => {
            lightbox.classList.remove("is-visible");
            if (this.soundEnabled) this.playTone(392.0, 0.16, "sine", 0.04);
          };

          const renderGallery = () => {
            grid.innerHTML = "";
            this.galleryItems.forEach((item, idx) => {
              const card = document.createElement("div");
              card.className = "photo-card";
              card.innerHTML = `





                    ${item.tag || "MOMEN KELAS"}

${item.title}


              `;
              card.addEventListener("click", () => openLightbox(idx));
              grid.appendChild(card);
            });
          };

          if (fileInput) {
            fileInput.addEventListener("change", () => {
              const file = fileInput.files && fileInput.files[0];
              if (!file) return;
              const reader = new FileReader();
              reader.onload = (ev) => {
                this.uploadedDataUrl = ev.target && ev.target.result ? String(ev.target.result) : "";
                if (srcInput) srcInput.value = file.name;
                if (fileHint) fileHint.textContent = `Terpilih: ${file.name}`;
              };
              reader.readAsDataURL(file);
            });
          }

          if (form) {
            form.addEventListener("submit", (e) => {
              e.preventDefault();
              const typedSrc = srcInput ? srcInput.value.trim() : "";
              const finalSrc = this.uploadedDataUrl || typedSrc || "foto1.jpg";
              const tagVal = (tagInput && tagInput.value.trim()) || "MOMEN KELAS";
              const titleVal = (titleInput && titleInput.value.trim()) || "Kenangan Baru";
              const descVal = (descInput && descInput.value.trim()) || "Tambahan foto kenangan bersama guru.";

              this.galleryItems.push({
                src: finalSrc,
                tag: tagVal.toUpperCase(),
                title: titleVal,
                desc: descVal
              });

              this.saveGallery();
              renderGallery();

              form.reset();
              this.uploadedDataUrl = "";
              if (fileHint) fileHint.textContent = "Foto berhasil ditambahkan ke galeri!";
              if (this.soundEnabled) this.playChimeChord();
            });
          }

          if (resetBtn) {
            resetBtn.addEventListener("click", () => {
              localStorage.removeItem(STORAGE_KEY);
              this.galleryItems = defaultGallery.map((item) => ({ ...item }));
              renderGallery();
              if (fileHint) fileHint.textContent = "Galeri dikembalikan ke 2 foto awal.";
            });
          }

          if (closeBtn) closeBtn.addEventListener("click", closeLightbox);
          if (prevBtn) prevBtn.addEventListener("click", () => openLightbox(this.activeGalleryIndex - 1));
          if (nextBtn) nextBtn.addEventListener("click", () => openLightbox(this.activeGalleryIndex + 1));

          lightbox.addEventListener("click", (e) => {
            if (e.target === lightbox) closeLightbox();
          });

          renderGallery();
        },

        setupGiftSection() {
          const boxBtn = document.getElementById("giftBoxBtn");
          const promptText = document.getElementById("giftPromptText");
          const panel = document.getElementById("giftRevealPanel");
          const celebrateBtn = document.getElementById("celebrateGiftBtn");
          if (!boxBtn || !panel) return;

          const triggerBurst = (el) => {
            const rect = el.getBoundingClientRect();
            const cx = rect.left + rect.width / 2;
            const cy = rect.top + rect.height / 2;
            if (this.burstParticles) this.burstParticles(cx, cy, 32);
            if (this.soundEnabled) this.playChimeChord();
          };

          boxBtn.addEventListener("click", () => {
            this.giftOpened = true;
            boxBtn.textContent = "🎊";
            boxBtn.classList.add("opened");
            panel.classList.add("is-open");
            if (promptText) promptText.textContent = "Kotak penghargaan telah terbuka!";
            triggerBurst(boxBtn);
          });

          if (celebrateBtn) {
            celebrateBtn.addEventListener("click", () => triggerBurst(celebrateBtn));
          }
        },

        setupEndingSection() {
          const btn = document.getElementById("triggerEndingBtn");
          const banner = document.getElementById("endingBanner");
          if (!btn || !banner) return;

          btn.addEventListener("click", () => {
            banner.classList.add("active");
            const rect = btn.getBoundingClientRect();
            if (this.burstParticles) {
              this.burstParticles(rect.left + rect.width / 2, rect.top, 40);
            }
            if (this.soundEnabled) {
              this.playChimeChord();
            }
            banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
          });
        },

        setupNavigationAndActions() {
          const startBtn = document.getElementById("startJourneyBtn");
          const giftJumpBtn = document.getElementById("quickGiftJump");
          const navLinks = document.querySelectorAll(".bottom-nav a");

          if (startBtn) {
            startBtn.addEventListener("click", () => {
              const target = document.getElementById("surat");
              if (target) target.scrollIntoView({ behavior: "smooth" });
              if (this.soundEnabled) this.playTone(523.25, 0.25, "triangle", 0.05);
            });
          }

          if (giftJumpBtn) {
            giftJumpBtn.addEventListener("click", () => {
              const target = document.getElementById("hadiah");
              if (target) target.scrollIntoView({ behavior: "smooth" });
              if (this.soundEnabled) this.playTone(587.33, 0.25, "triangle", 0.05);
            });
          }

          const sectionIds = ["hero", "surat", "galeri", "hadiah", "penutup"];
          const onScrollNav = () => {
            const pos = window.scrollY + window.innerHeight * 0.45;
            let currentId = "hero";

            sectionIds.forEach((id) => {
              const el = document.getElementById(id);
              if (el && el.offsetTop <= pos) {
                currentId = id;
              }
            });

            navLinks.forEach((link) => {
              const match = link.getAttribute("data-nav") === currentId;
              link.classList.toggle("active", match);
            });
          };

          window.addEventListener("scroll", onScrollNav, { passive: true });
          onScrollNav();
        }
      };

      if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", () => TributeApp.init());
      } else {
        TributeApp.init();
      }
    })();
